arguments.command:
cd /tmp/sv-5d9fc331dd484ba69f7be0c8e132962e
# Use nm to find the nearest symbol for those addresses
# First let's find what function contains 0x2f4b20 and 0x2f4c84
# Sort symbols and find the one just before each address
nm --defined-only -n libmonosgen-2.0.so.debug 2>/dev/null | awk '
/^[0-9a-f]+ [tTwW]/ { syms[NR]=$1; names[NR]=$3; count=NR }
END {
  targets["2f4b20"]=1; targets["2f4c84"]=1
  for (t in targets) {
    best=""
    for (i=1; i<=count; i++) {
      if (syms[i] <= t) best=names[i]
      else break
    }
    print "0x" t " -> " best
  }
}' 2>/dev/null || echo "nm approach failed"
# Alternative: use readelf
echo "---"
nm -n libmonosgen-2.0.so.debug 2>/dev/null | grep -B1 "2f4b" | head -4
echo "---"
nm -n libmonosgen-2.0.so.debug 2>/dev/null | awk '/^[0-9a-f]+ [tTwW]/{addr=$1; name=$3} addr && strtonum("0x"addr) <= strtonum("0x2f4b20") {last=name; lastaddr=addr} END{print lastaddr, last}' 2>/dev/null || true

